INSERT INTO `course` VALUES (1, '高数', 'https://image-aieducation.oss-cn-hangzhou.aliyuncs.com/ba9b047f-f335-4c00-bcf4-c5612b1ea32b.jpg', '1', '小明', '123456789', '高等数学作为一门广泛应用于各个领域的基础性学科，在高职院校中具有重要地位。', '理解并掌握高等数学的基本概念、基本理论和常用运算技能，包括函数的性质、极限与连续的概念、求函数极限的基本方法、导数及微分等在内的核心知识。', '培养学生灵活、抽象、猜想、活跃的数学思维，逐步形成数学意识，让数学这一工具进入到学生的生活实践中。');
